import Foundation
import Network
import MIWearPB
import MIWWifiSDK

internal class MIWBTSocketIO: MIWBTIO {

    private var socket: MIWBTSocket?
    private var canLoop = true
    private let socketSendSignal: MIWConditionLock = MIWConditionLock()
    private var currentWiFiInfo: MIWWiFiInfo?
    private var pendingGateway: String?
    private var openedWiFiAP: WearWiFiAP?

    private static let defaultPort: UInt16 = 30000

    deinit {
        MIWWiFiManager.shared.delegate = nil
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO deinit")
    }
}

extension MIWBTSocketIO: MIWPipeIOInterface {

    func startInit(cbPeri: any MIWCBPeripheralInterface, timeout: TimeInterval) {
        startConnection(timeout: timeout)
    }

    func startInit(btPeri: MIWBTPeripheral, timeout: TimeInterval) {
        self.btPeripheral = btPeri
        startConnection(timeout: timeout)
    }

    func cleanIOContext() {

        closeWiFiAPConfig()
    }

    func launchFire() -> Bool {
        self.txSignal.signal()
        return true
    }

    // MARK: - Connection

    private func startConnection(timeout: TimeInterval) {

        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO startConnection, fetching WiFi AP config")
        startTimeout(timeout * 2)
        fetchWiFiAPConfig()
    }

    // MARK: - Fetch WiFi AP Config via BLE

    private func fetchWiFiAPConfig() {

        guard let peripheral = self.btPeripheral else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO fetchWiFiAPConfig guard fail: btPeripheral is nil", level: .error)
            handleConnectionFailed(MIWBTDataLinkErrorCode.peripheralNil.toError())
            return
        }

        var packet = WearWearPacket()
        packet.type = .system
        packet.id = UInt32(WearSystem.SystemID.enableWifiAp.rawValue)

        let req = MIWBTReq(channel: .MIW_CHANNEL_PB, package: packet)
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO fetchWiFiAPConfig send enableWifiAp req, ident: \(req.identifier)")
        req.setResponseCallBack { [weak self] req, rsp in
            self?.handleWiFiAPResponse(rsp)
        }

        peripheral.executeRequest(req: req)
    }

    // MARK: - Close WiFi AP via BLE (disableWifiAp)

    private func closeWiFiAPConfig() {

        guard let peripheral = self.btPeripheral else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO closeWiFiAPConfig guard fail: btPeripheral is nil", level: .error)
            teardownResources()
            return
        }

        guard let wifiAP = self.openedWiFiAP else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO closeWiFiAPConfig guard fail: openedWiFiAP is nil, skip disableWifiAp", level: .error)
            teardownResources()
            return
        }
        self.openedWiFiAP = nil

        var sys = WearSystem()
        sys.wifiAp = wifiAP

        var packet = WearWearPacket()
        packet.type = .system
        packet.id = UInt32(WearSystem.SystemID.disableWifiAp.rawValue)
        packet.system = sys

        let req = MIWBTReq(channel: .MIW_CHANNEL_PB, package: packet)
        req.pipe = .MIW_BT_PIPE_P2P
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO closeWiFiAPConfig send disableWifiAp req, ident: \(req.identifier)")
        req.setReqSuccessCallBack { [weak self] req, rsp in
            MIWBTCoreLog("\(self?.pipeInfo.description() ?? "") MIWBTSocketIO closeWiFiAPConfig result, rspCode: \(rsp.rspCode)")
            self?.teardownResources()
        }

        peripheral.executeRequest(req: req)
    }

    private func teardownResources() {

        self.canLoop = false
        self.txSignal.signal()
        self.socketSendSignal.signal()

        self.txThread?.cancel()
        self.rxThread?.cancel()

        // 关闭 WiFi 前强等 3 秒，保证 socket 已入队数据全部发送完成，避免 WiFi 断开截断未发完的数据
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO wait 1s before close socket flush")
        Thread.sleep(forTimeInterval: 20.0)

        self.socket?.disconnect()
        self.socket = nil

        // 关闭 WiFi 前强等 3 秒，保证 socket 已入队数据全部发送完成，避免 WiFi 断开截断未发完的数据
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO wait 1s before close WiFi for socket flush")
        Thread.sleep(forTimeInterval: 20.0)

        MIWWiFiManager.shared.delegate = nil
        if let wifiInfo = self.currentWiFiInfo {
            MIWWiFiManager.disconnect(wifiInfo: wifiInfo)
            self.currentWiFiInfo = nil
        }

        // 资源释放完成后，通知 delegate IO 已关闭
        self.ioDelegateDidClose()
    }

    private func handleWiFiAPResponse(_ rsp: MIWBTRsp) {

        guard let result = rsp.package?.system.wifiApResult else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO handleWiFiAPResponse guard fail: wifiApResult is nil", level: .error)
            handleConnectionFailed(MIWBTDataLinkErrorCode.wifiApResultNil.toError())
            return
        }

        // 设备创建热点结果 code：0-成功 1-失败 2-省电模式 3-高温 4-录像 5-低温
        // code != 0 时设备未创建热点，ssid/password/gateway 通常为空，需先于字段校验判断，暴露真实失败原因
        guard result.code == 0 else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO handleWiFiAPResponse guard fail: wifi ap create failed, code=\(result.code)", level: .error)
            handleConnectionFailed(MIWBTError(domain: MIWBTDomain.miw_domain_data_link.rawValue,
                                              code: MIWBTDataLinkErrorCode.wifiApCreateFailed.rawValue,
                                              desc: "wifi ap create failed, code=\(result.code)"))
            return
        }

        let wifiAp = result.wifiAp
        let gateway = wifiAp.gateway
        let ssid = wifiAp.ssid
        let password = wifiAp.password

        guard !ssid.isEmpty else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO handleWiFiAPResponse guard fail: ssid is empty", level: .error)
            handleConnectionFailed(MIWBTDataLinkErrorCode.ssidEmpty.toError())
            return
        }

        guard !password.isEmpty else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO handleWiFiAPResponse guard fail: password is empty", level: .error)
            handleConnectionFailed(MIWBTDataLinkErrorCode.passwordEmpty.toError())
            return
        }

        guard !gateway.isEmpty else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO handleWiFiAPResponse guard fail: gateway is empty", level: .error)
            handleConnectionFailed(MIWBTDataLinkErrorCode.gatewayEmpty.toError())
            return
        }

        self.openedWiFiAP = wifiAp

        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO got WiFi AP ssid: \(ssid), gateway: \(gateway), connecting WiFi first")

        connectWiFi(ssid: ssid, password: password, gateway: gateway)
    }

    private func connectWiFi(ssid: String, password: String, gateway: String) {

        let wifiInfo = MIWWiFiInfo(ssid: ssid, password: password)
        self.currentWiFiInfo = wifiInfo
        self.pendingGateway = gateway

        MIWWiFiManager.shared.delegate = self
        MIWWiFiManager.connect(wifiInfo: wifiInfo)
    }

    private func connectSocket(gateway: String) {

        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO WiFi connected, connecting socket to \(gateway)")

        let sock = MIWBTSocket(host: gateway, port: MIWBTSocketIO.defaultPort)
        sock.delegate = self
        self.socket = sock
        sock.connect()
    }

    private func handleConnectionFailed(_ error: MIWBTError) {
        cancelTimeout()
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO connection failed: \(error.localizedDescription())", level: .error)

        if let dele = self.delegate {
            dele.ioDidOpen(io: self, error: error)
        }
    }

    // MARK: - RX

    private func startReceiving() {
        let rx = MIWBTThread.createThread(target: self, selt: #selector(rxTask), obj: self)
        rx.threadPriority = MIWBTThreadPriority.MIWBTThreadPriorityHight.rawValue
        self.rxThread = rx
        rx.start()
    }

    @objc private func rxTask(target: MIWBTSocketIO) {

        while target.canLoop {

            guard let socket = target.socket else {
                MIWBTCoreLog("\(target.pipeInfo.description()) MIWBTSocketIO rxTask guard fail: socket is nil, break rx loop", level: .error)
                break
            }
            let result = socket.receiveSync(maxLength: 4096)

            if let data = result.data, !data.isEmpty {
                if let receiver = target.receiver {
                    receiver.receiveModel(receiver: target,
                                          inModel: MIWIOModel(pipe: target.pipeInfo.pipeType,
                                                              dire: .MIW_IO_RX,
                                                              bytes: data,
                                                              seqn: 0))
                }
            }

            if let error = result.error {
                MIWBTCoreLog("\(target.pipeInfo.description()) MIWBTSocketIO receive error: \(error.localizedDescription())", level: .error)
                break
            }

            if result.isComplete {
                MIWBTCoreLog("\(target.pipeInfo.description()) MIWBTSocketIO connection closed by remote")
                break
            }
        }
    }

    // MARK: - TX

    @objc private func txTask(target: MIWBTSocketIO) {

        repeat {

            target.txSignal.lock()

            if let dele = target.dataSouce,
               let models = dele.getSendModel(out: target) {

                for io in models {
                    autoreleasepool {
                        target.sendSingleIOModel(target: target, model: io)
                    }
                }
            } else {
                if target.canLoop {
                    target.txSignal.wait()
                }
            }

            target.txSignal.unlock()

        } while target.canLoop
    }

    private func sendSingleIOModel(target: MIWBTSocketIO, model: MIWIOModel) {

        guard let socket = target.socket else {
            MIWBTCoreLog("\(target.pipeInfo.description()) MIWBTSocketIO sendSingleIOModel guard fail: socket is nil, skip send", level: .error)
            return
        }

        let processInfo = MIWSendProcessInfo(seqn: model.seqn)
        processInfo.cacheStartTime()
        model.sendStart(info: processInfo)

        var sendFailed = false
        repeat {

            let remaining = Int(model.count - model.offset)
            let chunkSize = min(remaining, 4096)
            let chunk = model.bytes[Int(model.offset)..<Int(model.offset) + chunkSize]

            if let error = socket.sendSync(Data(chunk)) {
                MIWBTCoreLog("\(target.pipeInfo.description()) MIWBTSocketIO send error: \(error.localizedDescription())", level: .error)
                sendFailed = true
                return
            }

            model.offset += UInt(chunkSize)
            model.sendProcess(info: processInfo)

        } while !sendFailed && target.canLoop && !model.complete && !model.canceled

        processInfo.cacheEndTime()
        model.sendEnd(info: processInfo)
    }
}

// MARK: - MIWBTSocketDelegate

extension MIWBTSocketIO: MIWBTSocketDelegate {

    func socketDidConnect(_ socket: MIWBTSocket) {

        self.cancelTimeout()
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO TCP connected to \(socket.host):\(socket.port)")

        self.startReceiving()

        let tx = MIWBTThread.createThread(target: self, selt: #selector(self.txTask), obj: self)
        tx.threadPriority = MIWBTThreadPriority.MIWBTThreadPriorityHight.rawValue
        self.txThread = tx
        tx.start()

        if let dele = self.delegate {
            dele.ioDidOpen(io: self, error: nil)
        }
    }

    func socketDidDisconnect(_ socket: MIWBTSocket, error: MIWBTError?) {

        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO connection cancelled")
        self.canLoop = false
        self.txSignal.signal()

        if let dele = self.delegate {
            dele.ioDidClose(io: self, error: error)
        }
    }

    func socketDidFail(_ socket: MIWBTSocket, error: MIWBTError) {
        handleConnectionFailed(error)
    }
}

// MARK: - MIWWiFiManagerDelegate

extension MIWBTSocketIO: MIWWiFiManagerDelegate {

    func wifiManager(didConnectWith wifiInfo: MIWWiFiInfo) {
        guard let gateway = self.pendingGateway else {
            MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO WiFi connected but pendingGateway is nil, ignored", level: .error)
            return
        }
        self.pendingGateway = nil
        connectSocket(gateway: gateway)
    }

    func wifiManager(didFailToConnectWith wifiInfo: MIWWiFiInfo, error: MIWWiFiError) {
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO WiFi connect failed: \(wifiInfo.ssid), error: \(error.localizedDescription)", level: .error)
        self.pendingGateway = nil
        handleConnectionFailed(MIWBTDataLinkErrorCode.wifiConnectFailed.toError())
    }

    func wifiManager(didDisconnectWith wifiInfo: MIWWiFiInfo) {
        MIWBTCoreLog("\(self.pipeInfo.description()) MIWBTSocketIO WiFi disconnected: \(wifiInfo.ssid), closing IO", level: .error)
        self.canLoop = false
        self.txSignal.signal()
        self.socket?.disconnect()

        if let dele = self.delegate {
            dele.ioDidClose(io: self, error: MIWBTDataLinkErrorCode.wifiDisconnected.toError())
        }
    }
}
